#ifndef TRITON_ADAPTER_UNSTRUCTURECONVERSION_H
#define TRITON_ADAPTER_UNSTRUCTURECONVERSION_H

#include "ascend/include/TritonToUnstructure/OffsetAnalysis.h"
#include "mlir/Pass/Pass.h"
