49	bool forceSimtTemplateFlag = false;
50	
51	namespace {
52	
53	constexpr int64_t kBitsPerByte = 8;
54	
55	static constexpr const char *kRouteDiscreteMaskToSimtAttrName =
56	    "route_discrete_mask_to_simt";
57	
58	static RankedTensorType resolvePtrTensorType(Value ptr) {
59	  auto ptrType = dyn_cast<RankedTensorType>(ptr.getType());
60	  if (auto ptrPtrType = dyn_cast<triton::PointerType>(ptr.getType())) {
61	    if (auto ptrTensorType =
62	            dyn_cast_or_null<RankedTensorType>(ptrPtrType.getPointeeType())) {
63	      ptrType = ptrTensorType;
64	    }
65	  }
66	  return ptrType;
67	}
68	
69	static Type getResultElementType(RankedTensorType ptrType) {
70	  auto resultElementType = ptrType.getElementType();
71	  if (auto pointerType =
72	          dyn_cast<triton::PointerType>(ptrType.getElementType())) {
73	    resultElementType = pointerType.getPointeeType();
74	  }
75	  return resultElementType;
76	}
77	
78	static int64_t getTypeSizeInByte(Type type) {
79	  if (auto intType = dyn_cast<IntegerType>(type)) {
80	    return intType.getWidth() / kBitsPerByte;
81	  }
82	  if (auto floatType = dyn_cast<FloatType>(type)) {
83	    return floatType.getWidth() / kBitsPerByte;
84	  }
85	  llvm_unreachable("Unhandled element type of tensor");
86	}
87	
88	template <typename MemAccOpTy>
89	void normalizeDiscreteMaskAccessForFallback(MemAccOpTy &op,
90	                                            PtrOffsetInfo &ptrOffsetInfo,
91	                                            PatternRewriter &rewriter) {
92	  if (!op->hasAttr(ConverterUtils::discreteMaskAttrName)) {
93	    return;
94	  }
95	
96	  if constexpr (std::is_same_v<MemAccOpTy, triton::StoreOp>) {
97	    auto selectOp = op.getValue().template getDefiningOp<arith::SelectOp>();
98	    op = rewriter.replaceOpWithNewOp<triton::StoreOp>(
99	        op, op.getPtr(), selectOp.getTrueValue(), selectOp.getCondition(),
100	        op.getCache(), op.getEvict());
101	  } else if constexpr (std::is_same_v<MemAccOpTy, triton::AtomicRMWOp>) {
102	    if (auto selectOp = op.getVal().template getDefiningOp<arith::SelectOp>()) {
103	      op = rewriter.replaceOpWithNewOp<triton::AtomicRMWOp>(
104	          op, op.getType(), op.getAtomicRmwOp(), op.getPtr(),
105	          selectOp.getTrueValue(), selectOp.getCondition(), op.getSem(),
106	          op.getScope());
107	    }
108	  }
109	
110	  rewriter.setInsertionPoint(op);
111	  ptrOffsetInfo.setUnstructured(ptrOffsetInfo.getRank());
112	}
113	
114	// ======================== 950 SIMT Indirect Fast-Path Lowering
115	// ========================
116	// 1. SIMT Fast-Path Gate
117	//    The SIMT indirect lowering path is enabled only when:
118	//      - compileOn91095Flag && forceSimtTemplateFlag
119	//      - and the access is either:
120	//          * unstructured, or has tag with 'route_discrete_mask_to_simt'
121	//
122	// 2. Op-Specific Lowering
123	//    (1) tt.load / tt.store
124	//        Entry requirements:
125	//          - SIMT fast-path gate enabled
126	//          - tensor rank <= 5, simt template only supports up to 5D tensors for
127	//          now
128	//        Lowering:
129	//          - tt.load / tt.store  -> tt.indirect_load / tt.indirect_store
130	//    (2) tt.atomic_rmw / tt.atomic_cas
131	//        Entry requirements:
132	//          - SIMT fast-path gate enabled
133	//          - offset/value/mask tensors have static shape (required for
134	//          flatten-to-1D lowering)
135	//        Lowering:
136	//          tt.atomic_rmw fadd, acq_rel, gpu, %src, %value, %mask
137	//          -> flatten offsets/data/mask to 1D
138	//          -> create a custom op:
139	//              hivm.hir.custom {
140	//                extra_attr = "operate=<atomic_op>"
141	//              } "__builtin_indirect_atomic" ins(%ptr, %offset, %value, %mask)
142	//              outs(%out)
143	//          -> reshape the returned 1D result back to the original tensor shape
144	//
145	// 3. Fallback Behavior
146	//    If SIMT indirect lowering cannot be formed for any operation,
147	//    conversion gracefully falls back to the legacy scalar-loop lowering path
148	// ======================================================================================
149	template <typename MemAccOpTy>
150	LogicalResult tryRewriteIndirectFastPath(MemAccOpTy op, Location loc,
151	                                         Value srcPtr, Value ptrOffset,
152	                                         ArrayRef<int64_t> resultShape,
153	                                         PatternRewriter &rewriter) {
154	  bool rankWithinIndirectLoadStoreFastPathLimit = resultShape.size() <= 5;
155	
156	  if constexpr (std::is_same_v<MemAccOpTy, triton::LoadOp>) {
157	    if (!rankWithinIndirectLoadStoreFastPathLimit) {
158	      return failure();
159	    }
160	
161	    assert(isa<triton::PointerType>(srcPtr.getType()) &&
162	           "src must be ptr type");
163	    Value mask = op.getMask();
164	    Value other = op.getOther();
165	    auto resultType = op.getType();
166	    auto newPtr = srcPtr;
167	    if (auto *defOp = srcPtr.getDefiningOp()) {
168	      if (auto intToPtrOp = dyn_cast<triton::IntToPtrOp>(defOp)) {
169	        auto zeroOffset = rewriter.create<arith::ConstantOp>(
170	            loc, rewriter.getZeroAttr(intToPtrOp.getSrc().getType()));
171	        newPtr = rewriter.create<triton::AddPtrOp>(loc, srcPtr.getType(),
172	                                                   srcPtr, zeroOffset);
173	      }
174	    }
175	    auto indirect = rewriter.create<triton::ascend::IndirectLoadOp>(
176	        loc, resultType, newPtr, ptrOffset, mask, other,
177	        ConverterUtils::requiresVolatileIndirectLoad(op.getPtr(), op));
178	    rewriter.replaceOp(op, indirect.getResult());
179	    LLVM_DEBUG({
180	      auto &os = llvm::dbgs();
181	      os << "Rewriting tt.load to tt.indirect_load\n";
182	      os << indirect << "\n";
183	    });
184	    return success();
185	  } else if constexpr (std::is_same_v<MemAccOpTy, triton::StoreOp>) {
186	    if (!rankWithinIndirectLoadStoreFastPathLimit) {
187	      return failure();
188	    }
189	
190	    assert(isa<triton::PointerType>(srcPtr.getType()) &&
191	           "src must be ptr type");
192	    Value value = op.getValue();
193	    Value mask = op.getMask();
194	
195	    // For bool store, unwrap ptr<i1> -> ptr<i8> bitcast before creating
196	    // indirect_store. Keep ptr<i1> so TypeConverter can map it to memref<?xi8>.
197	    if (auto bitcastOp = srcPtr.getDefiningOp<triton::BitcastOp>()) {
198	      auto srcPtrTy =
199	          dyn_cast<triton::PointerType>(bitcastOp.getSrc().getType());
200	      auto dstPtrTy = dyn_cast<triton::PointerType>(bitcastOp.getType());
201	
202	      if (srcPtrTy && dstPtrTy && srcPtrTy.getPointeeType().isInteger(1) &&
203	          dstPtrTy.getPointeeType().isInteger(8)) {
204	        srcPtr = bitcastOp.getSrc();
205	      }
206	    }
207	    auto indirect = rewriter.create<triton::ascend::IndirectStoreOp>(
208	        loc, srcPtr, ptrOffset, value, mask);
209	    rewriter.eraseOp(op);
210	    LLVM_DEBUG({
211	      auto &os = llvm::dbgs();
212	      os << "Rewriting tt.store to tt.indirect_store\n";
213	      os << indirect << "\n";
214	    });
215	    return success();
216	  } else if constexpr (std::is_same_v<MemAccOpTy, triton::AtomicRMWOp>) {
217	    assert(isa<triton::PointerType>(srcPtr.getType()) &&
218	           "src must be ptr type");
219	    if (!IndirectAtomicUtils::canUseIndirectAtomicFastPath(op, ptrOffset)) {
220	      return failure();
221	    }
222	
223	    auto customResult =
224	        IndirectAtomicUtils::tryConvertAtomicRmwToIndirectCustom(
225	            op, srcPtr, ptrOffset, rewriter);
226	    if (failed(customResult)) {
227	      return failure();
228	    }
229	
230	    rewriter.replaceOp(op, *customResult);
231	    LLVM_DEBUG({
232	      auto &os = llvm::dbgs();
233	      os << "Rewriting tt.atomic_rmw to hivm.hir.custom indirect atomic\n";
234	    });
235	    return success();
236	  } else if constexpr (std::is_same_v<MemAccOpTy, triton::AtomicCASOp>) {
237	    assert(isa<triton::PointerType>(srcPtr.getType()) &&
238	           "src must be ptr type");
239	    if (!IndirectAtomicUtils::canUseIndirectAtomicFastPath(op, ptrOffset)) {
240	      return failure();
241	    }
242	
243	    auto customResult =
244	        IndirectAtomicUtils::tryConvertAtomicCasToIndirectCustom(
245	            op, srcPtr, ptrOffset, rewriter);
246	    if (failed(customResult)) {
247	      return failure();
248	    }
249	
250	    rewriter.replaceOp(op, *customResult);
251	    LLVM_DEBUG({
252	      auto &os = llvm::dbgs();
253	      os << "Rewriting tt.atomic_cas to hivm.hir.custom indirect atomic\n";
254	    });
255	    return success();
256	  }
257	}
