261	template <typename MemAccOpTy>
262	bool UnstructuredMemAccessConverter<MemAccOpTy>::checkUnstructureAnnotated(
263	    MemAccOpTy op, PatternRewriter &rewriter) const {
264	  return llvm::any_of(op->getUsers(), [&rewriter](Operation *user) {
265	    auto annotationOp = dyn_cast<annotation::MarkOp>(user);
266	    if (annotationOp && annotationOp->hasAttr("mayDiscretememaccess")) {
267	      rewriter.eraseOp(annotationOp);
268	      return true;
269	    }
270	    return false;
271	  });
272	}
