287	template <typename MemAccOpTy>
288	Value UnstructuredMemAccessConverter<MemAccOpTy>::createExtractOp(
289	    Location loc, Value value, PatternRewriter &rewriter,
290	    ArrayRef<OpFoldResult> iterIdx) const {
291	  if (!value)
292	    return value;
293	  SmallVector<Value> indices;
294	  for (auto idxOfr : iterIdx) {
295	    auto idx = getValueOrCreateConstantIndexOp(rewriter, loc, idxOfr);
296	    indices.push_back(idx);
297	  }
298	  auto extractedOp = rewriter.create<tensor::ExtractOp>(loc, value, indices);
299	  extractedOp->setAttr(ConverterUtils::discreteAttrName,
300	                       UnitAttr::get(rewriter.getContext()));
301	  return extractedOp;
302	}
