304	template <typename MemAccOpTy>
305	Value UnstructuredMemAccessConverter<MemAccOpTy>::createExtractOp(
306	    Location loc, Value value, PatternRewriter &rewriter,
307	    ArrayRef<OpFoldResult> offsets, ArrayRef<OpFoldResult> sizes,
308	    ArrayRef<OpFoldResult> strides) const {
309	  if (!value)
310	    return value;
311	  LLVM_DEBUG({
312	    auto &os = llvm::dbgs();
313	    os << "Extracting\n";
314	    os << value << "\n";
315	  });
316	  auto extractedOp = rewriter.create<tensor::ExtractSliceOp>(
317	      loc, value, offsets, sizes, strides);
318	  extractedOp->setAttr(ConverterUtils::discreteAttrName,
319	                       UnitAttr::get(rewriter.getContext()));
320	  return extractedOp;
321	}
