332	template <>
333	template <typename... Args>
334	triton::AtomicRMWOp
335	UnstructuredMemAccessConverter<triton::AtomicRMWOp>::createMemAccOp(
336	    triton::AtomicRMWOp op, Value ptrToAccess, Location loc,
337	    PatternRewriter &rewriter, Args &&...args) const {
338	  auto extractedValue =
339	      createExtractOp(loc, op.getVal(), rewriter, std::forward<Args>(args)...);
340	  auto extractedMask =
341	      createExtractOp(loc, op.getMask(), rewriter, std::forward<Args>(args)...);
342	  Type targetType = ptrToAccess.getType();
343	  if (auto tensorType = dyn_cast<RankedTensorType>(targetType)) {
344	    auto ptrType = cast<triton::PointerType>(tensorType.getElementType());
345	    targetType =
346	        RankedTensorType::get(tensorType.getShape(), ptrType.getPointeeType());
347	  } else {
348	    auto resultType = cast<RankedTensorType>(op.getResult().getType());
349	    SmallVector<int64_t> scalarLikeShape(resultType.getRank(), 1);
350	    targetType =
351	        RankedTensorType::get(scalarLikeShape, resultType.getElementType());
352	    ptrToAccess = rewriter.create<triton::SplatOp>(
353	        loc, RankedTensorType::get(scalarLikeShape, ptrToAccess.getType()),
354	        ptrToAccess);
355	    extractedValue = rewriter.create<triton::SplatOp>(
356	        loc, RankedTensorType::get(scalarLikeShape, extractedValue.getType()),
357	        extractedValue);
358	    if (extractedMask) {
359	      extractedMask = rewriter.create<triton::SplatOp>(
360	          loc, RankedTensorType::get(scalarLikeShape, extractedMask.getType()),
361	          extractedMask);
362	    }
363	  }
364	  return rewriter.create<triton::AtomicRMWOp>(
365	      loc, targetType, op.getAtomicRmwOpAttr(), ptrToAccess, extractedValue,
366	      extractedMask, op.getSemAttr(), op.getScopeAttr());
367	}
