372	UnstructuredMemAccessConverter<triton::AtomicCASOp>::createMemAccOp(
373	    triton::AtomicCASOp op, Value ptrToAccess, Location loc,
374	    PatternRewriter &rewriter, Args &&...args) const {
375	  auto extractedCmp =
376	      createExtractOp(loc, op.getCmp(), rewriter, std::forward<Args>(args)...);
377	  auto extractedValue =
378	      createExtractOp(loc, op.getVal(), rewriter, std::forward<Args>(args)...);
379	  Type targetType = ptrToAccess.getType();
380	  if (auto tensorType = dyn_cast<RankedTensorType>(targetType)) {
381	    auto ptrType = cast<triton::PointerType>(tensorType.getElementType());
382	    targetType =
383	        RankedTensorType::get(tensorType.getShape(), ptrType.getPointeeType());
384	  } else {
385	    auto resultType = cast<RankedTensorType>(op.getResult().getType());
386	    SmallVector<int64_t> scalarLikeShape(resultType.getRank(), 1);
387	    targetType =
388	        RankedTensorType::get(scalarLikeShape, resultType.getElementType());
389	    ptrToAccess = rewriter.create<triton::SplatOp>(
390	        loc, RankedTensorType::get(scalarLikeShape, ptrToAccess.getType()),
391	        ptrToAccess);
392	    extractedCmp = rewriter.create<triton::SplatOp>(
393	        loc, RankedTensorType::get(scalarLikeShape, extractedCmp.getType()),
394	        extractedCmp);
395	    extractedValue = rewriter.create<triton::SplatOp>(
396	        loc, RankedTensorType::get(scalarLikeShape, extractedValue.getType()),
397	        extractedValue);
398	  }
399	  return rewriter.create<triton::AtomicCASOp>(
400	      loc, targetType, ptrToAccess, extractedCmp, extractedValue,
401	      op.getSemAttr(), op.getScopeAttr());
