417	template <>
418	template <>
419	void UnstructuredMemAccessConverter<triton::LoadOp>::splatAndLoadScenario<
420	    triton::LoadOp>(triton::LoadOp op, int rank,
421	                    PatternRewriter &rewriter) const {
422	  auto loc = op.getLoc();
423	  SmallVector<OpFoldResult> idx(rank, rewriter.getIndexAttr(0));
424	  auto extractedPtr = createExtractOp(loc, op.getPtr(), rewriter, idx);
425	  Value mask = op.getMask();
426	  Value other = op.getOther();
427	  Value loadedValue = rewriter.create<triton::LoadOp>(
428	      loc, extractedPtr, /*mask=*/nullptr, /*other=*/nullptr,
429	      /*boundaryCheck=*/ArrayRef<int32_t>(),
430	      /*PaddingOptionAttr=*/nullptr);
431	  loadedValue = rewriter.create<triton::SplatOp>(loc, op.getResult().getType(),
432	                                                 loadedValue);
433	  if (mask)
434	    rewriter.replaceOpWithNewOp<arith::SelectOp>(op, mask, loadedValue, other);
435	  else
436	    rewriter.replaceOp(op, loadedValue);
437	}
