439	template <typename MemAccOpTy>
440	UnstructuredMemAccessConverter<MemAccOpTy>::UnstructuredMemAccessConverter(
441	    MLIRContext *context, bool forceScalarizeMode,
442	    const llvm::DenseMap<Value, PtrOffsetInfo> &offsetMap,
443	    const llvm::SmallDenseMap<Value, bool> &fromTensorArg)
444	    : OpRewritePattern<MemAccOpTy>(context),
445	      forceScalarizeMode(forceScalarizeMode), offsetMap(offsetMap),
446	      fromTensorArg(fromTensorArg) {}
447	
448	template <typename MemAccOpTy>
449	LogicalResult UnstructuredMemAccessConverter<MemAccOpTy>::matchAndRewrite(
450	    MemAccOpTy op, PatternRewriter &rewriter) const {
451	  auto loc = op.getLoc();
452	
453	  auto ptr = op.getPtr();
454	  auto ptrType = resolvePtrTensorType(ptr);
455	  auto routeDiscreteMaskToSimt = op->hasAttr(kRouteDiscreteMaskToSimtAttrName);
456	
457	  if (!ptrType || op->hasAttr(ConverterUtils::discreteAttrName))
458	    return failure();
459	  if (!offsetMap.contains(ptr))
460	    return op.emitError() << "PtrOffsetInfo should be computed\n" << ptr;
461	
462	  auto ptrOffsetInfo = offsetMap.at(ptr);
463	
464	  if (checkUnstructureAnnotated(op, rewriter))
465	    ptrOffsetInfo.setUnstructured(ptrOffsetInfo.getRank());
466	
467	  if (ptrOffsetInfo.isStructured() && !routeDiscreteMaskToSimt &&
468	      (!ptrOffsetInfo.isScalarLike() ||
469	       llvm::all_of(ptrType.getShape(), [](int64_t dim) { return dim == 1; })))
470	    return failure();
471	
472	  LLVM_DEBUG({
473	    auto &os = llvm::dbgs();
474	    os << "Converting " << op->getName() << "\n";
475	    os << op << "\n";
476	    for (auto structured : ptrOffsetInfo.getStructuredRef())
477	      os << static_cast<int>(structured);
478	    os << "\n";
479	    os << ptrOffsetInfo.isScalarLike() << "\n";
480	  });
481	
482	  if constexpr (std::is_same_v<MemAccOpTy, triton::LoadOp>) {
483	    if (ptrOffsetInfo.isScalarLike()) {
484	      splatAndLoadScenario(op, ptrOffsetInfo.getRank(), rewriter);
485	      return success();
486	    }
487	  }
488	
489	  std::optional<MaskState> mstate = runMaskAnalysis(op, rewriter);
490	
491	  normalizeDiscreteMaskAccessForFallback(op, ptrOffsetInfo, rewriter);
492	
493	  if (forceScalarizeMode || ptrOffsetInfo.isScalarLike() ||
494	      fromTensorArg.at(ptr)) {
495	    ptrOffsetInfo.setUnstructured(ptrOffsetInfo.getRank());
496	  }
497	
498	  auto srcPtr = ptrOffsetInfo.getPtr();
499	  auto ptrOffset = ptrOffsetInfo.getOffset();
500	
501	  // LoadLike is operation with result
502	  bool isLoadLike = !op->use_empty();
503	
504	  Value zeroIdx =
505	      rewriter.create<arith::ConstantOp>(loc, rewriter.getIndexAttr(0));
506	  Value oneIdx =
507	      rewriter.create<arith::ConstantOp>(loc, rewriter.getIndexAttr(1));
508	  auto resultShape = ptrType.getShape();
509	  auto resultElementType = getResultElementType(ptrType);
510	  int64_t sizeInByte = getTypeSizeInByte(resultElementType);
511	
512	  for (int i = ptrOffsetInfo.getRank() - 1; i >= 0; i--) {
513	    if (!ptrOffsetInfo.isStructured(i))
514	      break;
515	    sizeInByte *= resultShape[i];
516	  }
517	
518	  // Force scalarize if memory is not aligned
519	  if (sizeInByte % 32 != 0) {
520	    ptrOffsetInfo.setUnstructured(ptrOffsetInfo.getRank());
521	  }
522	
523	  LLVM_DEBUG({
524	    auto &os = llvm::dbgs();
525	    os << "UnStructured Flag check:\n";
526	    os << "ptrOffsetInfo.isStructured: " << ptrOffsetInfo.isStructured()
527	       << "\n";
528	    os << "compileOn91095Flag: " << compileOn91095Flag << "\n";
529	    os << "forceSimtTemplateFlag: " << forceSimtTemplateFlag << "\n";
530	  });
531	
532	  // SIMT Indirect Fast-Path Lowering in 950 seiries
533	  bool indirectFastPathEnabled =
534	      compileOn91095Flag && forceSimtTemplateFlag &&
535	      ((!ptrOffsetInfo.isStructured() && sizeInByte < 64) ||
536	       routeDiscreteMaskToSimt);
537	  bool rankWithinIndirectLoadStoreFastPathLimit = resultShape.size() <= 5;
538	  if (indirectFastPathEnabled &&
539	      succeeded(tryRewriteIndirectFastPath(op, loc, srcPtr, ptrOffset,
540	                                           resultShape, rewriter))) {
541	    return success();
542	  }
543	
544	  LLVM_DEBUG({
545	    if (sizeInByte >= 64) {
546	      auto &os = llvm::dbgs();
547	      os << "Skip SIMT indirect fast path because continuous shape product is "
548	         << sizeInByte << " (>=64)\n";
549	    }
550	    if constexpr (std::is_same_v<MemAccOpTy, triton::LoadOp> ||
551	                  std::is_same_v<MemAccOpTy, triton::StoreOp>) {
552	      if (indirectFastPathEnabled &&
553	          !rankWithinIndirectLoadStoreFastPathLimit) {
554	        auto &os = llvm::dbgs();
555	        os << "Skip tt.indirect_load/store fast path because rank is "
556	           << resultShape.size() << " (>5), falling back to scalar loop path\n";
557	      }
558	    }
559	  });
560	
561	  Value iterArg = nullptr;
562	
563	  // Only load case
564	  if (isLoadLike) {
565	    iterArg =
566	        rewriter.create<tensor::EmptyOp>(loc, resultShape, resultElementType);
567	  }
568	  Value newOpResult = nullptr;
569	
570	  auto insertPoint = rewriter.saveInsertionPoint();
571	
572	  SmallVector<OpFoldResult> offsets;
573	  SmallVector<OpFoldResult> sizes;
574	  SmallVector<OpFoldResult> strides;
575	  SmallVector<int64_t> extractedShape;
576	
577	  for (size_t i = 0; i < resultShape.size(); i++) {
578	    auto size = resultShape[i];
579	    auto structured = ptrOffsetInfo.getStructuredRef()[i] ==
580	                      PtrOffsetInfo::AxisInfo::structured;
581	    // handle indirect dimension
582	    strides.push_back(rewriter.getIndexAttr(1));
583	    Value sizeVal =
584	        rewriter.create<arith::ConstantOp>(loc, rewriter.getIndexAttr(size));
585	    if (structured) {
586	      offsets.push_back(rewriter.getIndexAttr(0));
587	      sizes.push_back(rewriter.getIndexAttr(size));
588	      extractedShape.push_back(size);
589	    } else {
590	      scf::ForOp forOp;
591	      if (auto mtptOp =
592	              srcPtr.template getDefiningOp<triton::MakeTensorPtrOp>()) {
593	        auto tptShape = mtptOp.getShape()[i];
594	        if (tptShape.getType() != rewriter.getIndexType()) {
595	          tptShape = rewriter.create<arith::IndexCastOp>(
596	              loc, rewriter.getIndexType(), tptShape);
597	        }
598	        sizeVal = rewriter.create<arith::MinSIOp>(loc, sizeVal, tptShape);
599	      }
600	
601	      Value loopLower = zeroIdx;
602	      Value loopUpper = sizeVal;
603	      if (mstate && i < mstate->dims.size() && i < mstate->offsets.size()) {
604	        Value maskOffset =
605	            getValueOrCreateConstantIndexOp(rewriter, loc, mstate->offsets[i]);
606	        maskOffset = rewriter.create<arith::MaxSIOp>(loc, maskOffset, zeroIdx);
607	        maskOffset = rewriter.create<arith::MinSIOp>(loc, maskOffset, sizeVal);
608	        loopLower = maskOffset;
609	
610	        Value maskDim =
611	            getValueOrCreateConstantIndexOp(rewriter, loc, mstate->dims[i]);
612	        maskDim = rewriter.create<arith::AddIOp>(loc, maskOffset, maskDim);
613	        maskDim = rewriter.create<arith::MinSIOp>(loc, maskDim, sizeVal);
614	        loopUpper = maskDim;
615	      }
616	
617	      if (isLoadLike) {
618	        forOp = rewriter.create<scf::ForOp>(loc, loopLower, loopUpper, oneIdx,
619	                                            ValueRange({iterArg}));
620	        if (!newOpResult) {
621	          newOpResult = forOp->getResult(0);
622	        } else {
623	          rewriter.create<scf::YieldOp>(loc, forOp->getResult(0));
624	        }
625	        iterArg = forOp.getRegionIterArg(0);
626	      } else {
627	        forOp = rewriter.create<scf::ForOp>(loc, loopLower, loopUpper, oneIdx);
628	      }
629	      sizes.push_back(rewriter.getIndexAttr(1));
630	      offsets.push_back(forOp.getInductionVar());
631	      extractedShape.push_back(1);
632	      forOp->setAttr("ExtractedLoadOrStore",
633	                     UnitAttr::get(rewriter.getContext()));
634	      rewriter.setInsertionPointToStart(forOp.getBody());
635	    }
636	  }
637	
638	  bool fullyUnstructured = ptrOffsetInfo.isUnstructuredOrScalarlike();
639	  auto extractedType = RankedTensorType::get(extractedShape, resultElementType);
640	
641	  Value extractedOffset;
642	  if (fullyUnstructured) {
643	    if (auto mtptOp =
644	            srcPtr.template getDefiningOp<triton::MakeTensorPtrOp>()) {
645	      auto I64Type = rewriter.getIntegerType(64);
646	      srcPtr = mtptOp.getBase();
647	      extractedOffset = rewriter.create<arith::ConstantIntOp>(loc, 0, 64);
648	      for (auto [indVar, offset, stride] : llvm::zip_equal(
649	               offsets, ptrOffsetInfo.getOffsets(), mtptOp.getStrides())) {
650	        Value inductionVar = rewriter.create<arith::IndexCastOp>(
651	            loc, I64Type, cast<Value>(indVar));
652	        Value tptOffset = rewriter.create<arith::ExtSIOp>(loc, I64Type, offset);
653	        Value tptStride = rewriter.create<arith::ExtSIOp>(loc, I64Type, stride);
654	        tptOffset = rewriter.create<arith::MulIOp>(loc, tptStride, tptOffset);
655	        tptStride =
656	            rewriter.create<arith::MulIOp>(loc, tptStride, inductionVar);
657	        extractedOffset =
658	            rewriter.create<arith::AddIOp>(loc, extractedOffset, tptOffset);
659	        extractedOffset =
660	            rewriter.create<arith::AddIOp>(loc, extractedOffset, tptStride);
661	      }
662	    } else {
663	      extractedOffset = createExtractOp(loc, ptrOffset, rewriter, offsets);
664	    }
665	  } else {
666	    extractedOffset =
667	        createExtractOp(loc, ptrOffset, rewriter, offsets, sizes, strides);
668	  }
669	
670	  LLVM_DEBUG({
671	    auto &os = llvm::dbgs();
672	    os << "Extracted offset\n";
673	    os << extractedOffset << "\n";
674	  });
675	
676	  assert(isa<triton::PointerType>(srcPtr.getType()) && "src must be ptr type");
677	  if (!fullyUnstructured) {
678	    srcPtr = rewriter.create<triton::SplatOp>(
679	        loc, RankedTensorType::get(extractedShape, srcPtr.getType()), srcPtr);
680	  }
681	  Value ptrToAccess = rewriter.create<triton::AddPtrOp>(
682	      loc, srcPtr.getType(), srcPtr, extractedOffset);
683	
684	  MemAccOpTy accessedOp;
685	  if (fullyUnstructured) {
686	    accessedOp = createMemAccOp(op, ptrToAccess, loc, rewriter, offsets);
687	  } else {
688	    accessedOp =
689	        createMemAccOp(op, ptrToAccess, loc, rewriter, offsets, sizes, strides);
690	  }
691	
692	  accessedOp->setAttr(ConverterUtils::discreteAttrName,
693	                      UnitAttr::get(rewriter.getContext()));
694	
695	  if (isLoadLike) {
696	    assert(iterArg && "Load case must have iterArg in for loop");
697	
698	    Value value = accessedOp->getResult(0);
699	    Value result;
700	    if (!isa<RankedTensorType>(value.getType()) &&
701	        (std::is_same_v<MemAccOpTy, triton::AtomicRMWOp> ||
702	         std::is_same_v<MemAccOpTy, triton::AtomicCASOp>)) {
703	      value = rewriter.create<triton::SplatOp>(loc, extractedType, value);
704	    }
705	    if (!isa<RankedTensorType>(value.getType())) {
706	      SmallVector<Value> indices;
707	      for (auto idxOfr : offsets) {
708	        auto idx = getValueOrCreateConstantIndexOp(rewriter, loc, idxOfr);
709	        indices.push_back(idx);
710	      }
711	      result = rewriter.create<tensor::InsertOp>(loc, value, iterArg, indices);
712	    } else {
713	      result = rewriter.create<tensor::InsertSliceOp>(loc, value, iterArg,
714	                                                      offsets, sizes, strides);
715	    }
716	    rewriter.create<scf::YieldOp>(loc, result)
717	        ->setAttr(ConverterUtils::discreteAttrName,
718	                  UnitAttr::get(rewriter.getContext()));
719	    rewriter.restoreInsertionPoint(insertPoint);
720	    if constexpr (std::is_same_v<MemAccOpTy, triton::LoadOp>) {
721	      if (op.getMask() && op.getOther()) {
722	        rewriter
723	            .replaceOpWithNewOp<arith::SelectOp>(op, op.getMask(), newOpResult,
724	                                                 op.getOther())
725	            ->setAttr(ConverterUtils::discreteAttrName,
726	                      UnitAttr::get(rewriter.getContext()));
727	      } else {
728	        rewriter.replaceOp(op, newOpResult);
729	      }
730	    } else {
731	      rewriter.replaceOp(op, newOpResult);
732	    }
733	  } else {
734	    if constexpr (std::is_same_v<MemAccOpTy, triton::AtomicRMWOp>) {
735	      if (fullyUnstructured && accessedOp.getMask()) {
736	        auto mask = createExtractOp(
737	            loc, accessedOp.getMask(), rewriter,
738	            SmallVector<OpFoldResult>(ptrOffsetInfo.getRank(),
739	                                      rewriter.getIndexAttr(0)));
740	        rewriter.create<scf::IfOp>(loc, mask, [&](OpBuilder &b, Location loc) {
741	          b.create<triton::AtomicRMWOp>(
742	               loc, accessedOp.getType(), accessedOp.getAtomicRmwOp(),
743	               accessedOp.getPtr(), accessedOp.getVal(), nullptr,
744	               accessedOp.getSem(), accessedOp.getScope())
745	              ->setAttr(ConverterUtils::discreteAttrName,
746	                        UnitAttr::get(rewriter.getContext()));
747	          b.create<scf::YieldOp>(loc);
748	        });
749	        rewriter.eraseOp(accessedOp);
750	      }
751	    }
752	    rewriter.eraseOp(op);
753	  }
754	  LLVM_DEBUG({
755	    auto &os = llvm::dbgs();
756	    os << "After conversion\n"
757	       << ptrToAccess.getDefiningOp()
758	              ->template getParentOfType<triton::FuncOp>()
759	       << "\n";
760	  });
761	  return success();
762	}
763	
764	void TritonToUnstructurePass::runPreparse(LoopLikeOpInterface op) {
765	  IRRewriter rewriter(&getContext());
766	  auto loc = op.getLoc();
767	
768	  LLVM_DEBUG({
769	    auto &os = llvm::dbgs();
770	    os << "Pre-parsing " << op->getName() << "\n" << op << "\n";
771	  });
772	
773	  Block::BlockArgListType args;
774	  ValueRange yields;
775	  if (auto whileOp = dyn_cast<scf::WhileOp>(op.getOperation())) {
776	    args = whileOp.getBeforeArguments();
777	    yields = whileOp.getYieldOp().getOperands();
778	  } else {
779	    args = op.getRegionIterArgs();
780	    yields = op.getYieldedValues();
781	  }
782	
783	  for (auto [arg, yield] : llvm::zip_equal(args, yields)) {
784	    if (auto tensorType = dyn_cast<RankedTensorType>(yield.getType())) {
785	      parse(yield, loc, rewriter, offsetMapForLoopArgs);
786	      offsetMap[arg] = offsetMapForLoopArgs.at(yield);
787	      LLVM_DEBUG({
788	        auto &os = llvm::dbgs();
789	        os << "Pre-parsing result of\n" << arg << "\nis ";
790	        for (auto structured : offsetMap[arg].getStructuredRef())
791	          os << static_cast<int>(structured);
792	        os << '\n';
793	      });
794	    }
795	  }
796	}
797	
798	static bool isFromTensorArg(Value v,
799	                            llvm::SmallDenseMap<Value, bool> &fromTensorArg) {
800	  if (fromTensorArg.contains(v))
801	    return fromTensorArg.at(v);
802	  auto *defOp = v.getDefiningOp();
803	  if (!defOp) {
804	    fromTensorArg[v] = isa<RankedTensorType>(v.getType());
805	    return isa<RankedTensorType>(v.getType());
806	  }
807	  for (auto opr : defOp->getOperands()) {
808	    if (isFromTensorArg(opr, fromTensorArg)) {
809	      fromTensorArg[v] = true;
810	      return true;
811	    }
812	  }
813	  fromTensorArg[v] = false;
814	  return false;
815	}
816	
817	template <typename MemAccOpTy, typename>
818	void TritonToUnstructurePass::runParse(MemAccOpTy op) {
819	  IRRewriter rewriter(&getContext());
820	  LLVM_DEBUG({
821	    auto &os = llvm::dbgs();
822	    os << "Parsing " << op->getName() << "\n" << op << "\n";
823	  });
824	  parse(op.getPtr(), op.getLoc(), rewriter, offsetMap);
825	  isFromTensorArg(op.getPtr(), fromTensorArg);
826	}
827	
828	LogicalResult
829	TritonToUnstructurePass::processIfYieldAddHoistOperations(ModuleOp moduleOp) {
830	  mlir::RewritePatternSet patterns(&getContext());
831	  patterns.add<CannonicalizerConverter::IfYieldAddHoistConverter>(
832	      patterns.getContext());
833	  if (failed(applyPatternsGreedily(moduleOp, std::move(patterns)))) {
834	    moduleOp.emitWarning("IfYieldAddHoist processing failed");
835	    return failure();
836	  }
837	  return success();
838	}
839	
840	TritonToUnstructurePass::TritonToUnstructurePass(
841	    const TritonToUnstructureOptions &options)
842	    : TritonToUnstructureBase(options) {}
843	
844	void TritonToUnstructurePass::runOnOperation() {
845	  compileOn91095Flag = this->compileOn91095;
846	  forceSimtTemplateFlag = this->forceSimtTemplate;
847	
848	  LLVM_DEBUG({
849	    auto &os = llvm::dbgs();
850	    os << "TritonToUnstructurePass started with options:\n";
851	    os << "  compileOn91095: " << compileOn91095Flag << "\n";
852	    os << "  forceSimtTemplate: " << forceSimtTemplateFlag << "\n";
853	  });
854	
855	  ModuleOp moduleOp = getOperation();
856	  MLIRContext *ctx = &getContext();
857	
858	  moduleOp->walk([this](triton::FuncOp funcOp) {
859	    replacePtrArguments(funcOp, offsetMapForLoopArgs);
860	  });
861	  offsetMapForLoopArgs.clear();
862	
863	  if (failed(processIfYieldAddHoistOperations(moduleOp))) {
864	    moduleOp.emitWarning("Failed to process IfYieldAddHoist operations");
865	  }
866	
867	  moduleOp->walk([this](LoopLikeOpInterface op) { runPreparse(op); });
868	  moduleOp->walk([this](Operation *op) {
869	    if (auto loadOp = dyn_cast<triton::LoadOp>(op)) {
870	      runParse(loadOp);
871	    } else if (auto storeOp = dyn_cast<triton::StoreOp>(op)) {
872	      runParse(storeOp);
873	    } else if (auto atomicRMWOp = dyn_cast<triton::AtomicRMWOp>(op)) {
874	      runParse(atomicRMWOp);
875	    } else if (auto atomicCASOp = dyn_cast<triton::AtomicCASOp>(op)) {
876	      runParse(atomicCASOp);
877	    }
878	  });
879	
880	  RewritePatternSet patterns(ctx);
881	
882	  patterns.add<UnstructuredMemAccessConverter<triton::LoadOp>,
883	               UnstructuredMemAccessConverter<triton::StoreOp>,
884	               UnstructuredMemAccessConverter<triton::AtomicRMWOp>,
885	               UnstructuredMemAccessConverter<triton::AtomicCASOp>>(
886	      ctx, forceScalarizeMode, offsetMap, fromTensorArg);
887	
888	  LLVM_DEBUG({
889	    auto &os = llvm::dbgs();
890	    os << "Parsing done\n";
891	  });
892	
893	  if (failed(applyPatternsGreedily(moduleOp, std::move(patterns)))) {
894	    moduleOp->emitError("failed to apply Patterns");
895	    signalPassFailure();
896	  }
897	
898	  PassManager pm(&getContext(), moduleOp.getOperationName());
899	  pm.addPass(createCSEPass());
900	  pm.addPass(createCanonicalizerPass());
901	  if (failed(runPipeline(pm, getOperation()))) {
902	    signalPassFailure();
903	  }
904	}
