906	void TritonToUnstructurePass::getDependentDialects(
907	    DialectRegistry &registry) const {
908	  registry.insert<func::FuncDialect, arith::ArithDialect, linalg::LinalgDialect,
909	                  affine::AffineDialect, scf::SCFDialect, tensor::TensorDialect,
910	                  bufferization::BufferizationDialect, memref::MemRefDialect,
911	                  triton::TritonDialect, triton::ascend::TritonAscendDialect,
912	                  hivm::HIVMDialect>();
913	}
914	
915	std::unique_ptr<OperationPass<ModuleOp>> triton::createTritonToUnstructurePass(
916	    const TritonToUnstructureOptions &options) {
917	  return std::make_unique<TritonToUnstructurePass>(options);
918	}
