42	  Value tensorValue;
43	  if constexpr (std::is_same_v<ExtractOpTy, tensor::ExtractOp>) {
44	    tensorValue = op.getTensor();
45	  } else if constexpr (std::is_same_v<ExtractOpTy, tensor::ExtractSliceOp>) {
46	    tensorValue = op.getSource();
