51	    }
52	  } else {
53	    llvm_unreachable("Unhandled case");
54	  }
55	  auto funcOp = op->template getParentOfType<triton::FuncOp>();
56	  auto parentOp = tensorValue.getDefiningOp();
57	  auto loc = op.getLoc();
58	
59	  if (!parentOp || (!enableAggressiveMode && !parentOp->hasOneUse())) {
60	    return failure();
61	  }
