74	  } else if (auto mulIOp = dyn_cast<arith::MulIOp>(parentOp)) {
75	    bubbleUpIntBinaryOp(op, mulIOp, loc, rewriter);
76	  } else if (auto divSIOp = dyn_cast<arith::DivSIOp>(parentOp)) {
77	    bubbleUpIntBinaryOp(op, divSIOp, loc, rewriter);
78	  } else if (auto remSIOp = dyn_cast<arith::RemSIOp>(parentOp)) {
79	    bubbleUpIntBinaryOp(op, remSIOp, loc, rewriter);
80	  } else if (auto maxSIOp = dyn_cast<arith::MaxSIOp>(parentOp)) {
81	    bubbleUpIntBinaryOp(op, maxSIOp, loc, rewriter);
82	  } else if (auto minSIOp = dyn_cast<arith::MinSIOp>(parentOp)) {
83	    bubbleUpIntBinaryOp(op, minSIOp, loc, rewriter);
84	  } else if (auto andIOp = dyn_cast<arith::AndIOp>(parentOp)) {
85	    bubbleUpIntBinaryOp(op, andIOp, loc, rewriter);
86	  } else if (auto orIOp = dyn_cast<arith::OrIOp>(parentOp)) {
87	    bubbleUpIntBinaryOp(op, orIOp, loc, rewriter);
88	  } else if (auto cmpIOp = dyn_cast<arith::CmpIOp>(parentOp)) {
89	    bubbleUpOperation(op, cmpIOp, loc, rewriter);
90	  } else if (auto truncFOp = dyn_cast<arith::TruncFOp>(parentOp)) {
91	    bubbleUpOperation(op, truncFOp, loc, rewriter);
92	  } else if (auto extFOp = dyn_cast<arith::ExtFOp>(parentOp)) {
93	    bubbleUpOperation(op, extFOp, loc, rewriter);
94	  } else if (auto fpTosiOp = dyn_cast<arith::FPToSIOp>(parentOp)) {
95	    bubbleUpOperation(op, fpTosiOp, loc, rewriter);
96	  } else if (auto siTofpOp = dyn_cast<arith::SIToFPOp>(parentOp)) {
97	    bubbleUpOperation(op, siTofpOp, loc, rewriter);
98	  } else if (auto clampFOp = dyn_cast<triton::ClampFOp>(parentOp)) {
99	    bubbleUpOperation(op, clampFOp, loc, rewriter);
100	  } else if (auto addFOp = dyn_cast<arith::AddFOp>(parentOp)) {
101	    bubbleUpFloatBinaryOp<arith::AddFOp>(op, addFOp, loc, rewriter);
102	  } else if (auto subFOp = dyn_cast<arith::SubFOp>(parentOp)) {
103	    bubbleUpFloatBinaryOp<arith::SubFOp>(op, subFOp, loc, rewriter);
104	  } else if (auto mulFOp = dyn_cast<arith::MulFOp>(parentOp)) {
105	    bubbleUpFloatBinaryOp<arith::MulFOp>(op, mulFOp, loc, rewriter);
106	  } else if (auto divFOp = dyn_cast<arith::DivFOp>(parentOp)) {
107	    bubbleUpFloatBinaryOp(op, divFOp, loc, rewriter);
108	  } else if (auto minNumFOp = dyn_cast<arith::MinNumFOp>(parentOp)) {
109	    bubbleUpFloatBinaryOp<arith::MinNumFOp>(op, minNumFOp, loc, rewriter);
110	  } else if (auto maxNumFOp = dyn_cast<arith::MaxNumFOp>(parentOp)) {
111	    bubbleUpFloatBinaryOp<arith::MaxNumFOp>(op, maxNumFOp, loc, rewriter);
112	  } else if (auto cmpFOp = dyn_cast<arith::CmpFOp>(parentOp)) {
113	    bubbleUpOperation(op, cmpFOp, loc, rewriter);
114	  } else if (auto broadCastOp = dyn_cast<triton::BroadcastOp>(parentOp)) {
115	    bubbleUpOperation(op, broadCastOp, loc, rewriter);
116	  } else if (auto expandDimsOp = dyn_cast<triton::ExpandDimsOp>(parentOp)) {
117	    bubbleUpOperation(op, expandDimsOp, loc, rewriter);
118	  } else if (auto splatOp = dyn_cast<triton::SplatOp>(parentOp)) {
119	    bubbleUpOperation(op, splatOp, loc, rewriter);
120	  } else if (auto makeRangeOp = dyn_cast<triton::MakeRangeOp>(parentOp)) {
121	    bubbleUpOperation(op, makeRangeOp, loc, rewriter);
122	  } else if (auto addPtrOp = dyn_cast<triton::AddPtrOp>(parentOp)) {
123	    bubbleUpOperation(op, addPtrOp, loc, rewriter);
124	  } else if (auto floorOp = dyn_cast<math::FloorOp>(parentOp)) {
125	    bubbleUpOperation(op, floorOp, loc, rewriter);
126	  } else if (auto ceilOp = dyn_cast<math::CeilOp>(parentOp)) {
127	    bubbleUpOperation(op, ceilOp, loc, rewriter);
128	  } else if (auto extractSliceOp = dyn_cast<tensor::ExtractSliceOp>(parentOp)) {
129	    if constexpr (std::is_same_v<ExtractOpTy, tensor::ExtractOp>) {
130	      bubbleUpOperation(op, extractSliceOp, loc, rewriter);
131	    } else {
132	      return failure();
133	    }
134	  } else {
135	    return failure();
136	  }
137	  if (parentOp->use_empty())
138	    rewriter.eraseOp(parentOp);
139	
140	  LLVM_DEBUG({
141	    auto &os = llvm::dbgs();
142	    os << "After bubble up\n" << funcOp << '\n';
143	  });
144	
145	  return success();
146	}
