222	template <>
223	void BubbleUpExtract<tensor::ExtractOp>::bubbleUpOperation(
224	    tensor::ExtractOp op, triton::BroadcastOp parentOp, Location loc,
225	    PatternRewriter &rewriter) const {
226	  auto src = parentOp.getSrc();
227	  auto srcShape = cast<RankedTensorType>(src.getType()).getShape();
228	  SmallVector<Value> newIndices;
229	  for (const auto &[index, shape] :
230	       llvm::zip_equal(op.getIndices(), srcShape)) {
231	    if (shape == 1) {
232	      newIndices.push_back(
233	          rewriter.create<arith::ConstantOp>(loc, rewriter.getIndexAttr(0)));
234	    } else {
235	      newIndices.push_back(index);
236	    }
237	  }
238	  auto extractedOp = rewriter.create<tensor::ExtractOp>(loc, src, newIndices);
239	  extractedOp->setAttr(ConverterUtils::discreteAttrName,
240	                       UnitAttr::get(rewriter.getContext()));
241	  rewriter.replaceOp(op, extractedOp);
242	}
