244	template <>
245	void BubbleUpExtract<tensor::ExtractSliceOp>::bubbleUpOperation(
246	    tensor::ExtractSliceOp op, triton::BroadcastOp parentOp, Location loc,
247	    PatternRewriter &rewriter) const {
248	  auto src = parentOp.getSrc();
249	  auto srcShape = cast<RankedTensorType>(src.getType()).getShape();
250	  SmallVector<OpFoldResult> newOffsets;
251	  SmallVector<OpFoldResult> newSizes;
252	  bool isScalarLikeSrc = true;
253	  for (const auto &[offset, size, shape] :
254	       llvm::zip_equal(op.getMixedOffsets(), op.getMixedSizes(), srcShape)) {
255	    if (shape == 1) {
256	      newOffsets.push_back(rewriter.getIndexAttr(0));
257	      newSizes.push_back(rewriter.getIndexAttr(1));
258	    } else {
259	      newOffsets.push_back(offset);
260	      newSizes.push_back(size);
261	    }
262	    if (getConstantIntValue(newSizes.back()).value_or(-1) != 1)
263	      isScalarLikeSrc = false;
264	  }
265	  auto extractedType = getExtractSlicedType(newSizes, op.getDroppedDims(),
266	                                            getElementTypeOrSelf(src));
267	  auto extractedOp = rewriter.create<tensor::ExtractSliceOp>(
268	      loc, extractedType, src, newOffsets, newSizes, op.getMixedStrides());
269	  extractedOp->setAttr(ConverterUtils::discreteAttrName,
270	                       UnitAttr::get(rewriter.getContext()));
271	  if (isScalarLikeSrc) {
272	    SmallVector<Value> indices(
273	        extractedType.getRank(),
274	        rewriter.create<arith::ConstantOp>(loc, rewriter.getIndexAttr(0)));
275	    auto extractedValue =
276	        rewriter.create<tensor::ExtractOp>(loc, extractedOp, indices);
277	    rewriter.replaceOpWithNewOp<triton::SplatOp>(op, op.getResult().getType(),
278	                                                 extractedValue);
279	  } else {
280	    rewriter.replaceOpWithNewOp<triton::BroadcastOp>(
281	        op, op.getResult().getType(), extractedOp);
282	  }
283	}
