286	void BubbleUpExtract<tensor::ExtractOp>::bubbleUpOperation(
287	    tensor::ExtractOp op, triton::ExpandDimsOp parentOp, Location loc,
288	    PatternRewriter &rewriter) const {
289	  auto src = parentOp.getSrc();
290	  SmallVector<Value> newIndices;
291	  for (const auto index : llvm::enumerate(op.getIndices())) {
292	    if (index.index() != parentOp.getAxis())
293	      newIndices.push_back(index.value());
294	  }
295	  auto extractedOp = rewriter.create<tensor::ExtractOp>(loc, src, newIndices);
296	  extractedOp->setAttr(ConverterUtils::discreteAttrName,
297	                       UnitAttr::get(rewriter.getContext()));
