301	template <>
302	void BubbleUpExtract<tensor::ExtractSliceOp>::bubbleUpOperation(
303	    tensor::ExtractSliceOp op, triton::ExpandDimsOp parentOp, Location loc,
304	    PatternRewriter &rewriter) const {
305	  auto src = parentOp.getSrc();
306	  auto srcShape = cast<RankedTensorType>(src.getType()).getShape();
307	  auto offsets = op.getMixedOffsets();
308	  auto sizes = op.getMixedSizes();
309	  auto strides = op.getMixedStrides();
310	  auto axis = parentOp.getAxis();
311	  int64_t axisOffset = 0;
312	  SmallVector<OpFoldResult> newOffsets;
313	  SmallVector<OpFoldResult> newSizes;
314	  SmallVector<OpFoldResult> newStrides;
315	  auto droppedDim = op.getDroppedDims();
316	  llvm::SmallBitVector srcDroppedDims;
317	  for (size_t i = 0; i <= srcShape.size(); i++) {
318	    if (i != axis) {
319	      newOffsets.push_back(offsets[i]);
320	      newSizes.push_back(sizes[i]);
321	      newStrides.push_back(strides[i]);
322	      srcDroppedDims.push_back(droppedDim[i]);
323	      if (i < axis && droppedDim[i])
324	        axisOffset++;
325	    }
326	  }
327	  auto extractedType =
328	      getExtractSlicedType(newSizes, srcDroppedDims, getElementTypeOrSelf(src));
329	  if (extractedType == src.getType()) {
330	    rewriter.replaceOp(op, src);
331	  } else {
332	    auto extractedOp = rewriter.create<tensor::ExtractSliceOp>(
333	        loc, extractedType, src, newOffsets, newSizes, newStrides);
334	    extractedOp->setAttr(ConverterUtils::discreteAttrName,
335	                         UnitAttr::get(rewriter.getContext()));
336	    rewriter.replaceOpWithNewOp<triton::ExpandDimsOp>(op, extractedOp,
337	                                                      axis - axisOffset);
338	  }
339	}
