472	template <>
473	void BubbleUpExtract<tensor::ExtractOp>::bubbleUpOperation(
474	    tensor::ExtractOp op, tensor::ExtractSliceOp parentOp, Location loc,
475	    PatternRewriter &rewriter) const {
476	  SmallVector<Value> indices;
477	  SmallVector<Value> newIndices;
478	  auto indiceIter = op.getIndices().begin();
479	  auto droppedDims = parentOp.getDroppedDims();
480	  for (auto [idx, offset] : llvm::enumerate(parentOp.getMixedOffsets())) {
481	    if (droppedDims[idx]) {
482	      auto zeroIdx = rewriter.create<arith::ConstantOp>(
483	          op.getLoc(), rewriter.getIndexAttr(0));
484	      indices.push_back(zeroIdx);
485	    } else {
486	      indices.push_back(*indiceIter);
487	      ++indiceIter;
488	    }
489	  }
490	  for (const auto &[offset, index] :
491	       llvm::zip_equal(parentOp.getMixedOffsets(), indices)) {
492	    Value offsetVal =
493	        getValueOrCreateConstantIndexOp(rewriter, op.getLoc(), offset);
494	    newIndices.push_back(
495	        rewriter.create<arith::AddIOp>(op.getLoc(), offsetVal, index));
496	  }
497	  rewriter
498	      .replaceOpWithNewOp<tensor::ExtractOp>(op, parentOp.getSource(),
499	                                             newIndices)
500	      ->setAttr(ConverterUtils::discreteAttrName,
501	                UnitAttr::get(rewriter.getContext()));
502	}
