504	BubbleUpOperationPass::BubbleUpOperationPass(
505	    const BubbleUpOperationOptions &options)
506	    : BubbleUpOperationBase(options) {}
507	
508	void BubbleUpOperationPass::runOnOperation() {
509	  ModuleOp moduleOp = getOperation();
510	  MLIRContext *ctx = &getContext();
511	
512	  RewritePatternSet patterns(ctx);
513	  patterns.add<BubbleUpExtract<tensor::ExtractOp>,
514	               BubbleUpExtract<tensor::ExtractSliceOp>>(ctx,
515	                                                        enableAggressiveMode);
516	
517	  if (failed(applyPatternsGreedily(moduleOp, std::move(patterns)))) {
518	    moduleOp->emitError("failed to apply Patterns");
519	    signalPassFailure();
520	  }
521	
522	  PassManager pm(&getContext(), moduleOp.getOperationName());
523	  pm.addPass(createCSEPass());
524	  pm.addPass(createCanonicalizerPass());
525	  if (failed(runPipeline(pm, getOperation()))) {
526	    signalPassFailure();
527	  }
528	}
529	
530	std::unique_ptr<OperationPass<ModuleOp>>
531	triton::createBubbleUpOperationPass(const BubbleUpOperationOptions &options) {
532	  return std::make_unique<BubbleUpOperationPass>(options);
533	}
